// ---------- Feedback de rede / sincronização ----------
const ULTIMA_SYNC_KEY = 'perfilagem-ultima-sync-v1';
let ultimaSincronizacao = null; // timestamp (ms) da última vez que atualizarDoServidor() deu certo

function carregarUltimaSincronizacaoLocal(){
  try{
    const raw = localStorage.getItem(ULTIMA_SYNC_KEY);
    ultimaSincronizacao = raw ? Number(raw) : null;
  }catch(e){ ultimaSincronizacao = null; }
}

function registrarSincronizacaoOk(){
  ultimaSincronizacao = Date.now();
  try{ localStorage.setItem(ULTIMA_SYNC_KEY, String(ultimaSincronizacao)); }catch(e){}
  atualizarLabelUltimaSync();
}

// Texto relativo ("agora", "há 4 min", "há 2h") — atualizado a cada 30s por um
// timer, pra não precisar de uma nova sincronização só pra refletir o tempo passando.
function atualizarLabelUltimaSync(){
  const label = el('ultima-sync-label');
  if(!label) return;
  if(!ultimaSincronizacao){
    label.textContent = 'nunca sincronizado';
    return;
  }
  const segundos = Math.floor((Date.now() - ultimaSincronizacao) / 1000);
  let texto;
  if(segundos < 10) texto = 'sincronizado agora';
  else if(segundos < 60) texto = `sincronizado há ${segundos}s`;
  else if(segundos < 3600) texto = `sincronizado há ${Math.floor(segundos/60)}min`;
  else texto = `sincronizado há ${Math.floor(segundos/3600)}h`;
  label.textContent = texto;
}
setInterval(atualizarLabelUltimaSync, 30000);

let syncCounter = 0;
let syncTimer = null;
function syncStart(){
  syncCounter++;
  if(syncCounter === 1){
    syncTimer = setTimeout(()=>{
      document.body.classList.add('syncing');
      const badge = document.getElementById('sync-badge');
      if(badge) badge.style.display = 'inline-flex';
    }, 300);
  }
}
function syncEnd(){
  syncCounter = Math.max(0, syncCounter - 1);
  if(syncCounter === 0){
    clearTimeout(syncTimer);
    document.body.classList.remove('syncing');
    const badge = document.getElementById('sync-badge');
    if(badge) badge.style.display = 'none';
  }
}
const _fetchOriginal = window.fetch.bind(window);
window.fetch = function(...args){
  syncStart();
  // Garante que o contador de "sincronizando" sempre volta a zero, mesmo se a
  // rede ficar pendurada sem responder (senão o selo ficava preso na tela).
  let terminou = false;
  const fim = ()=>{ if(!terminou){ terminou = true; syncEnd(); } };
  const limite = setTimeout(fim, 20000);
  return _fetchOriginal(...args).finally(()=>{ clearTimeout(limite); fim(); });
};

function atualizarStatusConexao(){
  const banner = document.getElementById('offline-banner');
  if(banner) banner.style.display = navigator.onLine ? 'none' : 'block';
  // Sem internet: as alterações ficam guardadas neste aparelho (fila) — o banner avisa.
  document.body.classList.toggle('offline-leitura', !navigator.onLine);
  if(typeof atualizarIndicadorSalvamento === 'function') atualizarIndicadorSalvamento();
}
window.addEventListener('online', ()=>{
  atualizarStatusConexao();
  if(typeof falhasDeEnvio !== 'undefined' && falhasDeEnvio.size > 0) reenviarFalhas();
  // Sinal voltou (saiu do subsolo): se não há nada pendente, puxa o que os outros fizeram.
  setTimeout(async ()=>{
    if(typeof usuarioAtual === 'undefined' || !usuarioAtual) return;
    if(falhasDeEnvio.size > 0 || enviosEmAndamento > 0 || document.querySelector('.modal-overlay')) return;
    try{ if(await atualizarDoServidor()) showToast('Sinal voltou — dados atualizados.'); }catch(e){}
  }, 2500);
});
window.addEventListener('offline', atualizarStatusConexao);

// Sem internet o app continua EDITANDO: toda alteração entra na fila guardada no
// aparelho e sobe sozinha quando o sinal voltar. Só o que depende da rede de verdade
// fica bloqueado: fotos (upload), senha e nome de exibição (conta).
const SELETOR_SO_ONLINE = [
  '#btn-escolher-foto-leque', '#leque-foto-input', '#btn-escolher-foto-turno', '#foto-turno-input',
  '[onclick*="selecionarFotoLeque"]', '[onclick*="removerFotoLeque"]',
  '#btn-alterar-senha', '#btn-salvar-perfil', '#tecnico-nome', '#tecnico-senha-nova', '#tecnico-senha-confirma'
].join(',');
let ultimoAvisoOffline = 0;
function avisarSomenteConsulta(){
  if(Date.now() - ultimoAvisoOffline < 2500) return;
  ultimoAvisoOffline = Date.now();
  showToast('Isso precisa de internet (foto, senha ou nome). O resto você pode fazer — fica guardado e sobe quando o sinal voltar.');
}
function bloquearEdicaoOffline(e){
  if(navigator.onLine) return;
  const alvo = e.target && e.target.closest ? e.target.closest('button, input, select, textarea, label, [data-acao]') : null;
  if(!alvo) return;
  if(!(alvo.matches(SELETOR_SO_ONLINE) || alvo.closest(SELETOR_SO_ONLINE))) return;
  e.preventDefault();
  e.stopImmediatePropagation();
  avisarSomenteConsulta();
}
['click', 'change', 'input'].forEach(tipo=> document.addEventListener(tipo, bloquearEdicaoOffline, true));
document.addEventListener('beforeinput', bloquearEdicaoOffline, true);

// Avisa antes de fechar a aba se ainda há algo sem salvar.
window.addEventListener('beforeunload', (e)=>{
  if((typeof falhasDeEnvio !== 'undefined' && falhasDeEnvio.size > 0) || (typeof debouncesPendentes !== 'undefined' && debouncesPendentes.size > 0)){
    e.preventDefault();
    e.returnValue = '';
  }
});
document.addEventListener('click', (e)=>{
  if(e.target && e.target.closest && e.target.closest('#btn-reenviar-falhas')) reenviarFalhas();
});

