function toggleSelecaoLeque(id, marcado){
  if(marcado) lequesSelecionados.add(id);
  else lequesSelecionados.delete(id);
  renderExportBar();
  // reflete o destaque visual do card sem precisar re-renderizar a lista inteira
  document.querySelectorAll('.leque-group[data-leque-id="'+id+'"]').forEach(elGroup=>{
    elGroup.classList.toggle('selecionado', marcado);
  });
  // mantém em sincronia com a checklist da seção "Exportar turno" (mesma seleção, dois lugares)
  const chkTurno = document.querySelector('#turno-leques-checklist .turno-leque-check[data-id="'+id+'"]');
  if(chkTurno) chkTurno.checked = marcado;
}

function limparSelecaoLeques(){
  lequesSelecionados.clear();
  renderExportBar();
  render();
}

function renderExportBar(){
  const idsValidos = new Set(leques.map(l=>l.id));
  Array.from(lequesSelecionados).forEach(id=>{ if(!idsValidos.has(id)) lequesSelecionados.delete(id); });

  const bar = el('export-bar');
  const n = lequesSelecionados.size;
  if(n === 0){
    bar.style.display = 'none'; document.body.classList.remove('tem-export-bar');
    return;
  }
  bar.style.display = 'flex'; document.body.classList.add('tem-export-bar');
  const codigos = leques.filter(l=>lequesSelecionados.has(l.id))
    .sort((x,y)=> lequeCode(x).localeCompare(lequeCode(y), undefined, {numeric:true}))
    .map(l=>lequeCode(l)).join(', ');
  el('export-bar-count').textContent = (n===1 ? '1 leque selecionado: ' : n+' leques selecionados: ') + codigos;
}

// Lista, dentro da seção "Exportar turno", os leques do anel ativo pra marcar quais
// entram junto no PDF — só aparece quando o técnico responde "Sim" à pergunta acima.
// Usa o mesmo Set (lequesSelecionados) da seleção da lista principal, então marcar
// aqui ou lá embaixo dá no mesmo.
function renderTurnoLequesChecklist(){
  const wrap = el('turno-leques-wrap');
  const lista = el('turno-leques-checklist');
  const vazio = el('turno-leques-vazio');
  if(!wrap || !lista || !vazio) return;

  const grupo = el('turno-incluir-leques-group');
  const chipAtivo = grupo ? grupo.querySelector('.chip.active') : null;
  const incluir = chipAtivo ? chipAtivo.dataset.val === 'sim' : false;
  wrap.style.display = incluir ? '' : 'none';
  if(!incluir) return;

  const anelAtivo = aneis.find(a=>a.id===anelAtivoId);
  const lequesDoAnel = anelAtivo ? leques.filter(l=>l.anelId===anelAtivo.id) : [];
  const ordenados = [...lequesDoAnel].sort((x,y)=> lequeCode(x).localeCompare(lequeCode(y), undefined, {numeric:true}));

  if(ordenados.length === 0){
    lista.innerHTML = '';
    vazio.style.display = 'block';
    return;
  }
  vazio.style.display = 'none';

  lista.innerHTML = ordenados.map(l=>{
    const qtdFuros = furos.filter(f=>f.lequeId===l.id).length;
    const marcado = lequesSelecionados.has(l.id);
    return `
      <label class="turno-leque-item">
        <input type="checkbox" class="turno-leque-check" data-id="${l.id}" ${marcado ? 'checked' : ''}>
        <span class="info">
          <span class="code">${lequeCode(l)}</span>
          <span class="hint">${tipoLabel(l.tipo)}${l.nome ? ' · '+escHtml(l.nome) : ''} · ${qtdFuros} furo(s)</span>
        </span>
      </label>
    `;
  }).join('');
}

function uuidv4(){
  if(window.crypto && window.crypto.randomUUID) return window.crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c=>{
    const r = Math.random()*16|0, v = c==='x' ? r : (r&0x3|0x8);
    return v.toString(16);
  });
}

function salvarLocal(){
  try{
    localStorage.setItem(LOCAL_KEY, JSON.stringify({ aneis, leques, furos, anelAtivoId }));
  }catch(e){}
}
function carregarLocal(){
  try{
    const raw = localStorage.getItem(LOCAL_KEY);
    if(raw){
      const parsed = JSON.parse(raw);
      aneis = parsed.aneis || [];
      leques = parsed.leques || [];
      furos = parsed.furos || [];
      anelAtivoId = parsed.anelAtivoId || null;
    }
  }catch(e){}
}

// Nomes amigáveis pra tabela e pro tipo de ação, usados na lista de pendências.
// ---------- Envio direto ao servidor (sem fila) ----------
// Cada alteração vai pro Supabase na hora que acontece — não fica guardada
// esperando um botão "Enviar" nem um horário certo. Se estiver offline, o
// pedido simplesmente falha e a pessoa vê um aviso na hora, em vez de ficar
// "pendente" silenciosamente até o sinal voltar.

// Nomes amigáveis pra tabela — usados só nas mensagens de erro, pra dizer o
// que exatamente não foi salvo.
const NOME_TABELA_FILA = {
  aneis: 'Realce', leques: 'Leque', furos: 'Furo',
  turno_info: 'Dados do turno', turno_observacoes: 'Observação do turno',
  usuario_realce_ativo: 'Realce ativo', comunicados: 'Comunicado',
  checklist_furos: 'Marcação do checklist', checklist_leques: 'Leque do checklist', checklist_observacoes_gerais: 'Observação do checklist',
  equipes: 'Equipe', produtividade_lancamentos: 'Produção da equipe', projetos: 'Projeto', fotos_turno: 'Foto do turno'
};

// Pequeno atraso (debounce) só pras ações de update/upsert — evita mandar uma
// chamada de rede a cada letra digitada em campos como Local/Técnicos/DDS.
// Inserção e remoção continuam indo na hora, sem atraso nenhum.
const debouncesPendentes = new Map();
const registrosPendentes = new Map(); // chave -> registro acumulado esperando o debounce
const DEBOUNCE_MS = 500;

// ---------- Estado de salvamento ----------
// Mostra no topo se está salvando, se está tudo salvo ou se algo FALHOU. Uma
// falha fica na lista até ser reenviada com sucesso — não some como o toast.
const falhasDeEnvio = new Map(); // "tabela:acao:id" -> { tabela, acao, registro, motivo }
const enviosEmVoo = new Map();   // pedidos já disparados e ainda sem resposta (também vão pra fila guardada)

// ---------- Fila guardada no aparelho ----------
// Tudo que ainda não chegou ao servidor (falhou, está esperando o debounce ou está
// a caminho) é gravado no aparelho. Se o app fechar, o celular reiniciar ou o sinal
// só voltar amanhã, nada se perde: na próxima abertura a fila é restaurada e reenviada.
const FILA_KEY_PREFIXO = 'perfilagem-fila-v1:';
function chaveFilaDoUsuario(){ return (typeof usuarioAtual !== 'undefined' && usuarioAtual && usuarioAtual.id) ? FILA_KEY_PREFIXO + usuarioAtual.id : null; }
function itensDaFila(){
  const mapa = new Map();
  enviosEmVoo.forEach((v,k)=> mapa.set(k, v));
  if(typeof registrosPendentes !== 'undefined') registrosPendentes.forEach((reg, k)=>{
    const [tabela, acao] = k.split(':');
    mapa.set(k, { chave:k, tabela, acao, registro:reg });
  });
  falhasDeEnvio.forEach((v,k)=> mapa.set(k, { chave:v.chave, tabela:v.tabela, acao:v.acao, registro:v.registro, desde:v.desde }));
  return Array.from(mapa.values());
}
let filaRestauradaPara = null; // só grava a fila depois de ler a que já estava guardada (senão apagaria)
let filaRestauradaQtd = 0;
function persistirFila(){
  const k = chaveFilaDoUsuario(); if(!k) return;
  if(typeof usuarioAtual === 'undefined' || !usuarioAtual || filaRestauradaPara !== usuarioAtual.id) return;
  try{
    const itens = itensDaFila();
    if(itens.length) localStorage.setItem(k, JSON.stringify(itens));
    else localStorage.removeItem(k);
  }catch(e){}
}
function restaurarFilaPersistida(){
  const k = chaveFilaDoUsuario(); if(!k) return 0;
  if(filaRestauradaPara === usuarioAtual.id) return 0;
  filaRestauradaPara = usuarioAtual.id;
  let n = 0;
  try{
    const itens = JSON.parse(localStorage.getItem(k) || '[]');
    itens.forEach(it=>{
      if(!it || !it.tabela || !it.acao || !it.registro) return;
      const chave = it.chave || (it.tabela + ':' + it.acao + ':' + it.registro.id);
      if(falhasDeEnvio.has(chave)) return;
      falhasDeEnvio.set(chave, { chave, tabela:it.tabela, acao:it.acao, registro:it.registro, motivo:'guardado no aparelho', desde: it.desde || Date.now() });
      n++;
    });
  }catch(e){}
  filaRestauradaQtd += n;
  atualizarIndicadorSalvamento();
  persistirFila();
  return n;
}
function ehErroDeRede(msg){ return /failed to fetch|networkerror|load failed|network request failed|sem conex|timeout|fetch/i.test(String(msg||'')); }
function registrarFalhaNaFila(chave, tabela, acao, registro, motivo){
  const anterior = falhasDeEnvio.get(chave);
  // Duas alterações do mesmo registro enquanto offline viram UMA, com todos os campos.
  if(anterior && (acao === 'update' || acao === 'upsert')) registro = Object.assign({}, anterior.registro, registro);
  falhasDeEnvio.set(chave, { chave, tabela, acao, registro, motivo, desde: (anterior && anterior.desde) || Date.now() });
}
let enviosEmAndamento = 0;
let reenviandoFalhas = false;
const ORDEM_ACAO = { insert: 0, upsert: 1, update: 2, delete: 3 };

function atualizarIndicadorSalvamento(){
  const pill = document.getElementById('status-salvamento');
  const alerta = document.getElementById('alerta-falhas');
  const qtdFalhas = falhasDeEnvio.size;
  const salvando = enviosEmAndamento > 0 || debouncesPendentes.size > 0;
  if(pill){
    let estado, texto;
    if(qtdFalhas > 0){ estado = 'erro'; texto = `${qtdFalhas} sem salvar`; }
    else if(!navigator.onLine){ estado = 'offline'; texto = 'sem internet'; }
    else if(salvando){ estado = 'salvando'; texto = 'salvando...'; }
    else { estado = 'salvo'; texto = 'salvo'; }
    pill.className = 'status-salvamento ' + estado;
    pill.querySelector('.status-texto').textContent = texto;
    // "salvo" some depois de 2,5 s pra não ficar cobrindo campos e a barra de abas; qualquer
    // outro estado (salvando, sem internet, falha) continua visível até resolver.
    clearTimeout(pill._timerOculta);
    pill.classList.remove('discreto');
    if(estado === 'salvo') pill._timerOculta = setTimeout(()=> pill.classList.add('discreto'), 2500);
    pill.setAttribute('role', 'status');
    pill.setAttribute('aria-live', 'polite');
  }
  if(alerta){
    if(qtdFalhas === 0){ alerta.style.display = 'none'; return; }
    const nomes = Array.from(new Set(Array.from(falhasDeEnvio.values()).map(f=> NOME_TABELA_FILA[f.tabela] || f.tabela)));
    // Há quanto tempo a alteração mais antiga está parada: passando de 10 min, o aviso pede
    // pra subir até um ponto com sinal antes de trocar de turno (o que está só no aparelho
    // não chega ao gestor nem ao turno seguinte).
    const maisAntiga = Math.min(...Array.from(falhasDeEnvio.values()).map(f=> f.desde || Date.now()));
    const minParado = Math.floor((Date.now() - maisAntiga) / 60000);
    const longo = minParado >= 10;
    alerta.classList.toggle('longo', longo);
    alerta.querySelector('.alerta-falhas-texto').textContent = longo
      ? `⚠ ${qtdFalhas} alteração(ões) sem enviar há ${minParado} min (${nomes.join(', ')}). Suba até um ponto com sinal antes de trocar de turno, senão o próximo turno não vê o que você marcou.`
      : `${qtdFalhas} alteração(ões) guardada(s) neste aparelho, ainda não enviadas (${nomes.join(', ')}). Sobem sozinhas quando houver sinal — não precisa ficar com o app aberto.`;
    alerta.style.display = 'flex';
  }
}

async function reenviarFalhas(){
  if(reenviandoFalhas || falhasDeEnvio.size === 0) return;
  if(!navigator.onLine){ showToast('Sem internet. Quando o sinal voltar, toque em "Tentar de novo".'); return; }
  reenviandoFalhas = true;
  const btn = document.getElementById('btn-reenviar-falhas');
  if(btn){ btn.disabled = true; btn.textContent = 'Enviando...'; }
  const itens = Array.from(falhasDeEnvio.values()).sort((a,b)=> ORDEM_ACAO[a.acao] - ORDEM_ACAO[b.acao]);
  for(const f of itens){
    falhasDeEnvio.delete(f.chave);
    await executarEnvio(f.tabela, f.acao, f.registro, true);
    // Sem rede de verdade: não adianta tentar os outros agora (cada um esperaria o tempo limite).
    const voltou = falhasDeEnvio.get(f.chave);
    if(voltou && ehErroDeRede(voltou.motivo)) break;
  }
  persistirFila();
  reenviandoFalhas = false;
  if(btn){ btn.disabled = false; btn.textContent = 'Tentar de novo'; }
  atualizarIndicadorSalvamento();
  if(falhasDeEnvio.size === 0) showToast('Tudo salvo.');
}

let ultimoToastFalha = 0;
async function executarEnvio(tabela, acao, registro, silencioso){
  const chave = tabela + ':' + acao + ':' + registro.id;
  // Sem internet: nem tenta a rede — guarda na fila, sem barulho. O indicador "N sem salvar" já mostra.
  if(typeof navigator !== 'undefined' && navigator.onLine === false){
    registrarFalhaNaFila(chave, tabela, acao, registro, 'sem conexão');
    persistirFila();
    atualizarIndicadorSalvamento();
    return;
  }
  enviosEmAndamento++;
  enviosEmVoo.set(chave, { chave, tabela, acao, registro });
  persistirFila();
  atualizarIndicadorSalvamento();
  try{
    let error;
    if(acao === 'insert'){
      ({ error } = await db.from(tabela).insert(registro));
    }else if(acao === 'update'){
      const { id, ...resto } = registro;
      ({ error } = await db.from(tabela).update(resto).eq('id', id));
    }else if(acao === 'upsert'){
      ({ error } = await db.from(tabela).upsert(registro));
    }else if(acao === 'delete'){
      ({ error } = await db.from(tabela).delete().eq('id', registro.id));
    }
    if(error) throw error;
    falhasDeEnvio.delete(chave);
    if(acao === 'delete'){
      // apagou o registro: falhas antigas desse mesmo registro não fazem mais sentido
      Array.from(falhasDeEnvio.keys()).filter(k=> k.endsWith(':' + registro.id) && k.startsWith(tabela + ':')).forEach(k=> falhasDeEnvio.delete(k));
    }
  }catch(err){
    const motivo = err && err.message ? err.message : 'sem conexão';
    registrarFalhaNaFila(chave, tabela, acao, registro, motivo);
    // Falha de rede repetida não enche a tela de avisos: um aviso a cada 30 s no máximo.
    // O indicador "N sem salvar" continua mostrando que há pendências.
    const rede = ehErroDeRede(motivo);
    if(!silencioso && (!rede || Date.now() - ultimoToastFalha > 30000)){
      ultimoToastFalha = Date.now();
      const nomeTabela = NOME_TABELA_FILA[tabela] || tabela;
      showToast(rede ? 'Sem sinal: as alterações ficam guardadas neste aparelho e sobem quando a conexão voltar.' : `Não foi possível salvar (${nomeTabela}): ${motivo}`, { erro: !rede });
    }
  }finally{
    enviosEmVoo.delete(chave);
    enviosEmAndamento = Math.max(0, enviosEmAndamento - 1);
    persistirFila();
    atualizarIndicadorSalvamento();
  }
}

// Quem fez a marcação: nome (ou e-mail) de quem está logado. Vai junto com cada
// marcação do checklist pra equipe saber quem perfilou/topografou cada furo.
function nomeDoUsuario(){
  if(!usuarioAtual) return '';
  return usuarioAtual.nome || (usuarioAtual.email ? usuarioAtual.email.split('@')[0] : '');
}
function carimbarAutor(tabela, acao, registro){
  if(acao !== 'update' || !usuarioAtual) return;
  const eu = nomeDoUsuario();
  if(tabela === 'checklist_furos'){
    const f = checklistFuros.find(x=>x.id===registro.id);
    const eq = (typeof minhaEquipeId === 'function') ? minhaEquipeId() : null; // equipe fixa do usuário
    if('perfilado' in registro){ registro.perfilado_por = registro.perfilado ? eu : null; if(f) f.perfiladoPor = registro.perfilado ? eu : ''; if(eq && registro.perfilado){ registro.equipe_perfilagem_id = eq; if(f) f.equipePerfId = eq; } }
    if('topografado' in registro){ registro.topografado_por = registro.topografado ? eu : null; if(f) f.topografadoPor = registro.topografado ? eu : ''; if(eq && registro.topografado){ registro.equipe_topografia_id = eq; if(f) f.equipeTopoId = eq; } }
    if('obstruido' in registro){ registro.obstruido_por = registro.obstruido ? eu : null; if(f) f.obstruidoPor = registro.obstruido ? eu : ''; registro.equipe_obstrucao_id = (registro.obstruido && eq) ? eq : null; if(f) f.equipeObsId = (registro.obstruido && eq) ? eq : null; }
    if(f && eq && typeof completarEquipeDoLeque === 'function') setTimeout(()=>completarEquipeDoLeque(f.checklistLequeId), 0);
  }else if(tabela === 'checklist_leques' && 'perfilado' in registro){
    const c = checklistLeques.find(x=>x.id===registro.id);
    registro.perfilado_por = registro.perfilado ? eu : null; if(c) c.perfiladoPor = registro.perfilado ? eu : '';
  }
}

function enfileirar(tabela, acao, registro){
  carimbarAutor(tabela, acao, registro);
  // Insert e delete são ações discretas (um clique, não uma tecla) — vão na
  // hora, sem debounce, e cancelam qualquer debounce pendente pro mesmo registro.
  if(acao === 'insert' || acao === 'delete'){
    const chave = tabela + ':' + registro.id;
    const timerPendente = debouncesPendentes.get(chave);
    if(timerPendente){ clearTimeout(timerPendente); debouncesPendentes.delete(chave); }
    executarEnvio(tabela, acao, registro);
    return;
  }
  // update/upsert: agrupa chamadas rápidas seguidas (ex: digitando num campo)
  // numa só, depois de uma pequena pausa.
  const chave = tabela + ':' + acao + ':' + registro.id;
  const timerAnterior = debouncesPendentes.get(chave);
  if(timerAnterior) clearTimeout(timerAnterior);
  // Duas alterações seguidas no mesmo registro (ex.: perfilado e depois topografado)
  // viram UM envio com os dois campos — antes a segunda apagava a primeira.
  const anterior = registrosPendentes.get(chave);
  if(anterior) registro = Object.assign({}, anterior, registro);
  registrosPendentes.set(chave, registro);
  persistirFila();
  const novoTimer = setTimeout(()=>{
    debouncesPendentes.delete(chave);
    registrosPendentes.delete(chave);
    executarEnvio(tabela, acao, registro); // já entra em "em voo" (e na fila guardada) de forma síncrona
  }, DEBOUNCE_MS);
  debouncesPendentes.set(chave, novoTimer);
  atualizarIndicadorSalvamento();
}
// estado inicial (online/offline) — só depois de falhasDeEnvio e debouncesPendentes existirem
atualizarStatusConexao();

// Antes cancelava um item pendente na fila (ex: ao apagar um leque, cancela o
// furo dele que ainda não tinha sido enviado). Sem fila, isso não existe mais
// — mas a função continua aqui (sem fazer nada) pra não precisar mexer em
// cada lugar que ainda chama ela.
function removerDaFila(tabela, id){}

// Sempre que troca ou cria o anel ativo, já preenche o "Local" do turno com o nome
// do anel + o nível cadastrado nele (ex: "Realce N3-Leste · N-125 TR6733") — evita
// digitar a mesma informação duas vezes. Só sincroniza quando o anel tem um nível de
// fato; se estiver vazio, não apaga o que a pessoa já tinha digitado em Local.
// Sempre que troca ou cria o anel ativo, já preenche o "Local" do turno com o
// código/nome do anel — e o nível também, se estiver cadastrado (ex: "32PE12"
// ou "32PE12 · N-125 TR6733"). Antes só sincronizava quando tinha nível
// preenchido, o que deixava o Local sem atualizar pra quem usa o próprio
// código do anel como nome, sem separar num campo de nível.
function sincronizarLocalComNivelDoAnel(){
  const anel = aneis.find(a=>a.id===anelAtivoId);
  if(!anel) return;
  const campoLocal = el('turno-local');
  if(campoLocal) campoLocal.value = anel.nivel ? `${anel.nome} · ${anel.nivel}` : anel.nome;
  // O campo Projeto do turno é só-leitura — segue automaticamente o projeto
  // associado ao realce ativo (configurado na criação/edição do realce).
  const campoProjeto = el('turno-projeto');
  if(campoProjeto) campoProjeto.value = anel.projeto || '';
  saveTurnoInfo();
}

// Realce ativo é POR USUÁRIO: cada pessoa tem o seu, guardado na tabela
// usuario_realce_ativo (1 linha por usuário). A coluna aneis.ativo não é mais
// escrita — só serve de ponto de partida pra quem ainda não escolheu nenhum.
function gravarRealceAtivoDoUsuario(anelId){
  if(!usuarioAtual || !usuarioAtual.id) return;
  enfileirar('usuario_realce_ativo', 'upsert', { id: usuarioAtual.id, anel_id: anelId || null, atualizado_em: new Date().toISOString() });
}

function definirAnelAtivo(novoId){
  anelAtivoId = novoId;
  gravarRealceAtivoDoUsuario(novoId);
  sincronizarLocalComNivelDoAnel();
  // Limpa os filtros da lista de furos ao trocar de anel — um filtro (principalmente
  // a busca por texto) que fizesse sentido no anel anterior pode não bater com nada
  // no novo, fazendo a tela parecer vazia sem nenhuma pista visível do motivo.
  if(el('f-tipo')) el('f-tipo').value = '';
  if(el('f-situacao')) el('f-situacao').value = '';
  if(el('f-busca')) el('f-busca').value = '';
  if(typeof atualizarContadorFiltros === 'function') atualizarContadorFiltros();
}

// O Supabase devolve no maximo 1000 linhas por consulta; pagina ate trazer tudo
// (sem isso, tabelas grandes como checklist_furos e furos ficam cortadas).
async function buscarTudo(tabela){
  const TAM = 1000;
  let todas = [];
  for(let de = 0; ; de += TAM){
    const { data, error } = await db.from(tabela).select('*').order('criado_em').order('id').range(de, de + TAM - 1);
    if(error) return { data: null, error };
    todas = todas.concat(data || []);
    if(!data || data.length < TAM) break;
  }
  return { data: todas, error: null };
}

// Busca a versão mais recente do servidor. Só sobrescreve o que está local
// se não houver nada pendente (pra nunca perder alterações ainda não enviadas).
async function atualizarDoServidor(){
  if(!navigator.onLine) return false;
  // Nunca troca os dados locais pelos do servidor enquanto houver alteração sua
  // ainda não enviada — senão as marcações feitas sem sinal "sumiriam" da tela.
  if(falhasDeEnvio.size > 0 || debouncesPendentes.size > 0 || enviosEmAndamento > 0) return false;
  try{
    // produtividade_lancamentos é tolerante: se a tabela ainda não foi criada no Supabase, não derruba o resto da sincronização
    const eqResp = await buscarTudo('equipes');
    const prodResp = await buscarTudo('produtividade_lancamentos');
    if(!eqResp.error && !prodResp.error){
      equipes = (eqResp.data || []).map(mapEquipe);
      lancamentosProd = (prodResp.data || []).map(mapLancamento);
    }
    const comResp = await buscarTudo('comunicados');
    if(!comResp.error){ comunicados = (comResp.data || []).map(mapComunicado); salvarComunicadosLocal(); }
    const [{ data: aneisData, error: e1 }, { data: lequesData, error: e2 }, { data: furosData, error: e3 }, { data: obsData, error: e4 }, { data: fotosData, error: e5 }, { data: checklistData, error: e6 }, { data: checklistFurosData, error: e7 }, { data: checklistObsGeralData, error: e8 }, { data: projetosData, error: e9 }] = await Promise.all([
      buscarTudo('aneis'),
      buscarTudo('leques'),
      buscarTudo('furos'),
      buscarTudo('turno_observacoes'),
      buscarTudo('fotos_turno'),
      buscarTudo('checklist_leques'),
      buscarTudo('checklist_furos'),
      buscarTudo('checklist_observacoes_gerais'),
      buscarTudo('projetos')
    ]);
    if(e1 || e2 || e3 || e4 || e5 || e6 || e7 || e8 || e9) throw (e1 || e2 || e3 || e4 || e5 || e6 || e7 || e8 || e9);
    aneis = (aneisData || []).map(mapAnel);
    leques = (lequesData || []).map(mapLeque);
    furos = (furosData || []).map(mapFuro);
    turnoObservacoes = (obsData || []).map(mapObservacao);
    fotosTurno = (fotosData || []).map(mapFotoTurno);
    checklistLeques = (checklistData || []).map(mapChecklistLeque);
    checklistFuros = (checklistFurosData || []).map(mapChecklistFuro);
    checklistObservacoesGerais = (checklistObsGeralData || []).map(mapObservacaoGeralChecklist);
    projetos = (projetosData || []).map(mapProjeto);
    // Realce ativo do usuário logado: 1) o que ele escolheu (servidor), 2) o que
    // estava ativo neste aparelho, 3) o antigo "ativo" global, 4) o primeiro.
    let escolhaServidor = null;
    if(usuarioAtual && usuarioAtual.id){
      const { data: linha, error: eU } = await db.from('usuario_realce_ativo').select('anel_id').eq('id', usuarioAtual.id).maybeSingle();
      if(!eU && linha) escolhaServidor = linha.anel_id;
    }
    const existe = id => id && aneis.some(a=>a.id===id);
    const legado = aneis.find(a=>a.ativo);
    const escolhido = existe(escolhaServidor) ? escolhaServidor
      : existe(anelAtivoId) ? anelAtivoId
      : legado ? legado.id : (aneis[0] ? aneis[0].id : null);
    anelAtivoId = escolhido;
    if(escolhido && escolhido !== escolhaServidor) gravarRealceAtivoDoUsuario(escolhido);
    sincronizarLocalComNivelDoAnel();
    salvarLocal();
    salvarObsLocal();
    salvarFotosTurnoLocal();
    salvarChecklistLocal();
    salvarChecklistFurosLocal();
    salvarChecklistObsGeralLocal();
    salvarProjetosLocal();
    salvarEquipesLocal();
    salvarProdutividadeLocal();
    renderAll();
    renderComunicados();
    renderObservacoesTurno();
    renderFotosTurno();
    registrarSincronizacaoOk();
    return true;
  }catch(e){
    return false;
  }
}

async function sincronizarDoServidor(){
  if(!navigator.onLine){
    showToast('Sem conexão agora. Tente de novo quando tiver sinal.');
    return;
  }
  const btn = el('btn-atualizar');
  btn.disabled = true;
  const htmlOriginal = btn.innerHTML;
  btn.innerHTML = '<svg class="icon-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>Atualizando...';
  if(falhasDeEnvio.size > 0) await reenviarFalhas();
  const pendente = falhasDeEnvio.size > 0 || debouncesPendentes.size > 0 || enviosEmAndamento > 0;
  const ok = pendente ? false : await atualizarDoServidor();
  btn.disabled = false;
  btn.innerHTML = htmlOriginal;
  showToast(ok ? 'Dados atualizados a partir do servidor.' : pendente ? 'Ainda há alterações suas sem enviar. Elas sobem quando houver sinal; só então os dados são atualizados.' : 'Não foi possível atualizar agora. Tente de novo.', { erro: false });
}

el('btn-atualizar').addEventListener('click', sincronizarDoServidor);

async function loadData(){
  carregarLocal();
  carregarUltimaSincronizacaoLocal();
  carregarFotosTurnoLocal();
  carregarChecklistLocal();
  carregarChecklistFurosLocal();
  carregarChecklistObsGeralLocal();
  carregarProjetosLocal();
  if(!anelAtivoId && aneis[0]) anelAtivoId = aneis[0].id;
  sincronizarLocalComNivelDoAnel();
  renderAll();
  atualizarLabelUltimaSync();
  // Alterações que ficaram guardadas (app fechado/sem sinal) sobem antes de qualquer atualização.
  const restauradas = restaurarFilaPersistida() + filaRestauradaQtd;
  filaRestauradaQtd = 0;
  if(restauradas > 0){
    showToast(`${restauradas} alteração(ões) guardada(s) de antes: ${navigator.onLine ? 'enviando agora…' : 'sobem quando o sinal voltar.'}`, { erro:false });
    if(navigator.onLine) await reenviarFalhas();
  }
  await atualizarDoServidor();
}

// Atualiza o texto do aviso de alterações paradas (minutos sem enviar) a cada minuto.
setInterval(()=>{ if(falhasDeEnvio.size > 0) atualizarIndicadorSalvamento(); }, 60000);

// Tentativa automática: com pendências e rede disponível, reenvia a cada 30 s
// (cobre Wi-Fi sem internet que "volta" sem disparar o evento online).
setInterval(()=>{
  if(typeof usuarioAtual === 'undefined' || !usuarioAtual) return;
  if(!navigator.onLine || reenviandoFalhas || falhasDeEnvio.size === 0 || enviosEmAndamento > 0) return;
  reenviarFalhas().then(()=>{ if(falhasDeEnvio.size === 0 && debouncesPendentes.size === 0) atualizarDoServidor(); });
}, 30000);
// Ao esconder o app (trocar de app, bloquear a tela), garante que a fila está gravada.
document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState === 'hidden') persistirFila(); });
window.addEventListener('pagehide', persistirFila);

const historicoToasts = []; // { texto, ts } — últimos avisos, pra quem perdeu o toast na hora

function showToast(msg, opcoes){
  opcoes = opcoes || {};
  const t = el('toast');
  clearTimeout(t._timer);

  // Erros não somem sozinhos: ficam até a pessoa tocar em "OK" (em subsolo,
  // ninguém está olhando a tela no segundo em que o aviso aparece).
  const ehErro = opcoes.erro != null ? opcoes.erro : /^(N[ãa]o foi poss[íi]vel|Erro|Sem conex[ãa]o|Falha)/i.test(msg);
  t.classList.toggle('erro', ehErro);
  // tipo do aviso: cor e ícone próprios (sucesso, atenção, erro, info)
  const tipo = ehErro ? 'erro' : (opcoes.tipo || (/^(Sem (conex|internet)|Ainda há|Nenhum|Já existe|Preencha|Atenção)/i.test(msg) ? 'aviso' : (/(salv|atualizad|registrad|criad|removid|marcad|perfilad|topografad|enviad|volt|liberad|Tudo)/i.test(msg) ? 'ok' : 'info')));
  t.dataset.tipo = tipo;
  if(opcoes.acaoLabel && opcoes.onAcao){
    t.innerHTML = `<span>${escHtml(msg)}</span><button type="button" class="toast-acao">${opcoes.acaoLabel}</button>`;
    t.querySelector('.toast-acao').addEventListener('click', ()=>{
      clearTimeout(t._timer);
      t.classList.remove('show');
      opcoes.onAcao();
    });
  }else if(ehErro){
    t.innerHTML = `<span>${escHtml(msg)}</span><button type="button" class="toast-acao toast-ok">OK</button>`;
    t.querySelector('.toast-ok').addEventListener('click', ()=>{ clearTimeout(t._timer); t.classList.remove('show'); });
  }else{
    t.innerHTML = `<span>${escHtml(msg)}</span>`;
  }

  t.classList.remove('show'); void t.offsetWidth;
  t.classList.add('show');
  // com botão de ação, fica mais tempo na tela — precisa de uma folga pra dar
  // tempo de ler e decidir se quer desfazer, não só "ver passar".
  const duracao = opcoes.acaoLabel ? 7000 : 2600;
  if(!ehErro) t._timer = setTimeout(()=> t.classList.remove('show'), duracao);

  historicoToasts.unshift({ texto: msg, ts: Date.now() });
  if(historicoToasts.length > 30) historicoToasts.length = 30;
}

function tempoRelativo(ts){
  const segundos = Math.floor((Date.now() - ts) / 1000);
  if(segundos < 10) return 'agora';
  if(segundos < 60) return `há ${segundos}s`;
  if(segundos < 3600) return `há ${Math.floor(segundos/60)}min`;
  return `há ${Math.floor(segundos/3600)}h`;
}

// Lista os últimos avisos — útil pra quem estava olhando pra outro lado quando o
// toast apareceu e quer conferir depois o que aconteceu.
function abrirModalHistoricoToasts(){
  const root = el('modal-root');
  if(historicoToasts.length === 0){
    root.innerHTML = `
      <div class="modal-overlay" id="modal-overlay">
        <div class="modal-box">
          <p style="font-weight:700;">Nenhum aviso ainda</p>
          <p class="hint">As mensagens que aparecem no canto da tela (furo adicionado, erro de envio, etc.) ficam listadas aqui.</p>
          <div class="modal-actions">
            <button class="ghost" id="modal-fechar">Fechar</button>
          </div>
        </div>
      </div>
    `;
  }else{
    const linhas = historicoToasts.map(item=>`
      <div class="fila-item">
        <span class="hint" style="white-space:nowrap;">${tempoRelativo(item.ts)}</span>
        <span class="desc">${escHtml(item.texto)}</span>
      </div>
    `).join('');
    root.innerHTML = `
      <div class="modal-overlay" id="modal-overlay">
        <div class="modal-box">
          <p style="font-weight:700;">Últimos avisos</p>
          <div class="fila-lista">${linhas}</div>
          <div class="modal-actions">
            <button class="ghost" id="modal-fechar">Fechar</button>
          </div>
        </div>
      </div>
    `;
  }
  const fechar = ()=>{ root.innerHTML = ''; };
  el('modal-fechar').addEventListener('click', fechar);
  el('modal-overlay').addEventListener('click', (e)=>{ if(e.target.id === 'modal-overlay') fechar(); });
}
el('btn-historico-toast').addEventListener('click', abrirModalHistoricoToasts);


function confirmDialog(mensagem, textoConfirmar){
  return new Promise(resolve=>{
    const root = el('modal-root');
    const perigoso = /remover|apagar|excluir|finalizar|mesmo assim|⚠|NÃO/i.test(mensagem + ' ' + (textoConfirmar || ''));
    root.innerHTML = `
      <div class="modal-overlay" id="modal-overlay">
        <div class="modal-box modal-confirma ${perigoso ? 'perigoso' : ''}" role="alertdialog" aria-modal="true">
          <div class="modal-ico" aria-hidden="true">${perigoso ? '⚠' : '?'}</div>
          <p>${mensagem}</p>
          <div class="modal-actions">
            <button class="ghost" id="modal-cancelar">Cancelar</button>
            <button class="${perigoso ? 'danger' : 'steel'}" id="modal-confirmar">${textoConfirmar || 'Confirmar'}</button>
          </div>
        </div>
      </div>
    `;
    const fechar = (resultado)=>{ root.innerHTML = ''; resolve(resultado); };
    el('modal-cancelar').addEventListener('click', ()=> fechar(false));
    el('modal-confirmar').addEventListener('click', ()=> fechar(true));
    el('modal-overlay').addEventListener('click', (e)=>{ if(e.target.id === 'modal-overlay') fechar(false); });
    el('modal-cancelar').focus();
  });
}

